-- composition of rule kernels cte_inlining x duplicate_groups (duckdb), template graft_scalar
WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 5) SELECT TRUE AS c0, [1, 2, 3]::int[] AS c1, 1.5::numeric AS c2, LEAST (LEAST (1.5::numeric, (SELECT MAX (100.0::numeric) FROM v0 AS a2 WHERE COALESCE (COALESCE ((a1.c0 BETWEEN 16 AND 3), TRUE), FALSE))), NULL::numeric) AS c3 FROM (SELECT * FROM v0 WHERE (SELECT count(*) FROM (SELECT ((COUNT (DISTINCT a1.c1) % 1000)::int - 1) AS c0, a1.c1 AS c1, 'A'::text AS c2, 1::bigint AS c3 FROM tl AS a1 GROUP BY a1.c1) AS kb) >= 0) AS a1;
